style.css:
@-moz-document domain("youtube.com") {
/* Change general or specific text to Green */
  yt-formatted-string, 
  #video-title {
    color: #00FF00 !important; /* Green text */
  }

  /* Change specific elements (like badges, likes, or alerts) to Red */
  #owner-name, 
  #text.ytd-button-renderer {
    color: #FF0000 !important; /* Red text */
  }
}
